cypress_script:
describe('Broken Images Accessibility Test', () => {
  it('should display the correct title and heading', () => {
    cy.visit('https://the-internet.herokuapp.com/broken_images');
    cy.title().should('eq', 'The Internet');
    cy.get('h1').should('have.text', 'Broken Images');
  });
  it('should verify the footer is displayed', () => {
    cy.visit('https://the-internet.herokuapp.com/broken_images');
    cy.get('#page-footer').should('be.visible');
  });
});

playwright_script:
import { test, expect } from '@playwright/test';

test.describe('Broken Images Accessibility Test', () => {
  test('should display the correct title and heading', async ({ page }) => {
    await page.goto('https://the-internet.herokuapp.com/broken_images');
    await expect(page).toHaveTitle('The Internet');
    const heading = await page.locator('h1');
    await expect(heading).toHaveText('Broken Images');
  });
  test('should verify the footer is displayed', async ({ page }) => {
    await page.goto('https://the-internet.herokuapp.com/broken_images');
    const footer = await page.locator('#page-footer');
    await expect(footer).toBeVisible();
  });
});
